#include "sg3_sequence.hpp"
#include "resource_root.hpp"
#include "cg_image_conversion.hpp"
#include <cstdlib>
#include <iostream>
#include <filesystem>
int main(int argc,char**argv){const char*env=std::getenv("EMPEROR_GAMEDATA_ROOT");if(!env||!*env){std::cout<<"{\"skipped\":true}\n";return 0;}if(argc!=3)return 2;auto root=game_lab::ResourceRoot::fromAbsolute(env);auto path=root.resolve(argv[1]);if(path.empty())return 2;auto a=game_lab::loadSG3(path);auto ids=game_lab::parseSG3SequenceIds(argv[2],a.sprites.size());if(!ids)return 2;auto companion=std::filesystem::path(path);companion.replace_extension(".555");auto seq=game_lab::prepareSG3Sequence(a,*ids,companion.string(),true);if(!seq.valid())return 1;size_t native=0,distinct=0,exact=0;for(size_t i=0;i<seq.frames.size();++i){const auto&im=seq.frames[i];auto cg=game_lab::createCGImageFromPremultipliedBGRA(im.width,im.height,im.pixelsBGRA);if(cg){++native;CGImageRelease(cg);}if(i&&im.pixelsBGRA!=seq.frames[i-1].pixelsBGRA)++distinct;
 const auto&record=a.sprites[(*ids)[i]-1];const auto source=game_lab::decodeSG3Sprite(a,(*ids)[i]-1,companion.string()).image;int minX=32768,minY=32768;for(auto id:*ids){minX=std::min(minX,-int(a.sprites[id-1].animationOffsetX));minY=std::min(minY,-int(a.sprites[id-1].animationOffsetY));}const size_t x=size_t(-int(record.animationOffsetX)-minX),y=size_t(-int(record.animationOffsetY)-minY);bool same=source.valid();for(size_t row=0;same&&row<source.height;++row)same=std::equal(source.pixelsBGRA.begin()+row*source.width,source.pixelsBGRA.begin()+(row+1)*source.width,im.pixelsBGRA.begin()+(row+y)*im.width+x);exact+=same;}
 std::cout<<"{\"skipped\":false,\"frames\":"<<seq.frames.size()<<",\"native_images\":"<<native<<",\"exact_source_frames\":"<<exact<<",\"adjacent_different\":"<<distinct<<",\"adjacent_pairs\":"<<seq.frames.size()-1<<",\"canvas_width\":"<<seq.frames[0].width<<",\"canvas_height\":"<<seq.frames[0].height<<",\"cache_bytes\":"<<seq.cacheBytes<<",\"original_timing_verified\":false,\"automatic_frame_chain\":false}\n";return native==seq.frames.size()&&exact==seq.frames.size()?0:1;}
